import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Watchlists and research","description":"Adding/importing assets, alert context, asset research, comparison, and moving research into a decision or journal workflow.","frontmatter":{"title":"Watchlists and research","description":"Adding/importing assets, alert context, asset research, comparison, and moving research into a decision or journal workflow.","audience":"user","status":"current","last_verified":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"use-zenin/watchlists-and-research.md","filePath":"use-zenin/watchlists-and-research.md","lastUpdated":null}'),s={name:"use-zenin/watchlists-and-research.md"};function n(i,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="watchlists-and-research" tabindex="-1">Watchlists and research</h1><p>Watchlists and research work together: a watchlist tells Zenin what to watch, and research explains why it matters to your portfolio.</p><h2 id="adding-and-importing-assets" tabindex="-1">Adding and importing assets</h2><p>From <strong>Watchlist</strong> you can:</p><ul><li><strong>Search</strong> by symbol (<code>AAPL</code>, <code>BTC</code>, <code>SPY</code>, <code>EUR/USD</code>) and add.</li><li><strong>Import</strong> a list from CSV/TSV, spreadsheet, platform text, or document workflows.</li><li>Organize items into <strong>categorized watchlists</strong>.</li></ul><h2 id="alert-context" tabindex="-1">Alert context</h2><p>Turn on <strong>alerts</strong> for watched items where your plan allows. Alerts are tied to the instrument and surface in Notifications.</p><h2 id="asset-research" tabindex="-1">Asset research</h2><p>Open an asset from Watchlist, Portfolio, Home, or an Intelligence surface to launch <strong>Research</strong>. Research brings together:</p><ul><li>company, commodity, macro, or ETF context depending on the instrument;</li><li>portfolio-aware actions (add to watchlist, open in portfolio, start a journal entry);</li><li>related-market handoffs.</li></ul><h2 id="comparison" tabindex="-1">Comparison</h2><p>Use <strong>compare</strong> to weigh an asset against a peer (for example, one ETF against another). ETF research shows fund-focused fields and comparisons; stock-only company metrics are not presented as ETF data. FX-pair research distinguishes a tradable pair from a standalone currency entity.</p><h2 id="moving-research-into-a-decision-or-journal" tabindex="-1">Moving research into a decision or journal</h2><p>Research is most useful when it becomes a recorded decision:</p><ol><li>Open the asset and review the relevant context.</li><li>Use a portfolio-aware action to <strong>start a decision</strong> or <strong>journal entry</strong>.</li><li>Paste or summarize the rationale so the decision and the outcome can be reviewed later.</li></ol><p>This closes the loop from market signal to documented decision.</p><hr><h2 id="what-this-does-does-not-do" tabindex="-1">What this does / does not do</h2><p><strong>What this does</strong></p><ul><li>Lets you track multi-asset watchlists and import them in bulk.</li><li>Opens contextual research tied to your portfolio.</li><li>Hands research off to a decision or journal workflow.</li></ul><p><strong>What it does not do</strong></p><ul><li>It does not guarantee live prices for every instrument — coverage is provider-dependent.</li><li>It does not treat a currency code as a tradable instrument with fabricated prices.</li><li>It does not auto-create journal entries; you choose to record them.</li></ul><p><strong>Data source and freshness</strong></p><p>Watchlist items are user-defined. Research data comes from the configured providers (company/fundamentals, market data, macro, commodities) and may be current, delayed, stale, or reference-only by instrument and provider.</p>',24)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
